import type { PaymentCheckout } from "@btst/stack/payments";
/** Host-local wall-clock interval, using HH:mm and exclusive end (24:00 allowed). */
export type TimeInterval = { start: string; end: string };
/** Repeating host availability; Sunday is 0 and Saturday is 6. */
export type WeeklyAvailability = TimeInterval & { dayOfWeek: number };
/** Replaces weekly availability on a host-local YYYY-MM-DD date; [] blocks the date. */
export type DateOverride = { date: string; intervals: TimeInterval[] };
/** Reserved attendee limits per event type, in host-local calendar periods; total is lifetime. */
export type BookingLimits = {
	perHour?: number;
	perDay?: number;
	perWeek?: number;
	total?: number;
};

/** Event configuration serialized for HTTP and React Query. Duration is real elapsed minutes. */
export type EventType = {
	id: string;
	hostId: string;
	slug: string;
	name: string;
	description: string;
	location: string;
	duration: number;
	capacity: number;
	/** Enable verified email waitlists for full group slots. */
	waitlistEnabled?: boolean;
	/** Optional nonnegative price in minor currency units; null/zero means free. */
	price?: number | null;
	/** Three-letter uppercase currency code, supplied together with price. */
	currency?: string | null;
	timezone: string;
	weeklyAvailability: WeeklyAvailability[];
	dateOverrides: DateOverride[];
	limits: BookingLimits;
	active: boolean;
	createdAt: string;
	updatedAt: string;
};

/** Reservation with ISO instants. cancelToken is a private bearer secret; management responses redact it. */
export type Booking = {
	id: string;
	eventTypeId: string;
	hostId: string;
	eventName: string;
	start: string;
	end: string;
	timezone: string;
	name: string;
	email: string;
	status: "confirmed" | "pending_payment" | "cancelled";
	cancelToken: string;
	/** Whether this booking has an adapter-managed checkout. */
	hasCheckout?: boolean;
	createdAt: string;
};

/** UTC ISO slot instants and the remaining attendee reservations, including booking limits. */
export type AvailableSlot = { start: string; end: string; remaining: number };
/** External calendar occupancy as absolute instants, with an exclusive end. */
export type BusyInterval = { start: Date; end: Date };
/** Availability for one viewer-local date in the requested IANA timezone. */
export type Availability = {
	slots: AvailableSlot[];
	/** Full group slots that still satisfy all other scheduling rules. */
	waitlistSlots?: AvailableSlot[];
	date: string;
	timezone: string;
};

/** Storage shape: structured configuration is JSON text and timestamps are Date values. */
export type EventTypeRecord = Omit<
	EventType,
	"weeklyAvailability" | "dateOverrides" | "limits" | "createdAt" | "updatedAt"
> & {
	weeklyAvailability: string;
	dateOverrides: string;
	limits: string;
	createdAt: Date;
	updatedAt: Date;
};

/** Storage shape of a reservation, including its private cancellation token. */
export type BookingRecord = Omit<Booking, "start" | "end" | "createdAt"> & {
	/** Private provider state, never serialized into booking reads. */
	payment?: string | null;
	start: Date;
	end: Date;
	createdAt: Date;
};

/** Checkout is returned only on reservation or token-authorized checkout requests. */
export type BookingCheckout = Booking & {
	checkout?: PaymentCheckout;
	checkoutError?: string;
};

/** Safe connection details returned to the owning host. Credentials remain in the application. */
export type CalendarConnection = {
	id: string;
	provider: "google" | "microsoft";
	label: string;
	calendarId: string | null;
	calendarName: string | null;
	status: "connected" | "disconnecting" | "disconnected";
};

export type ProviderCalendar = { id: string; name: string };

/** Persisted outbox entry and provider event mapping, visible only to its owning host. */
export type CalendarSyncState = {
	id: string;
	bookingId: string;
	connectionId: string;
	calendarId: string;
	eventId: string | null;
	state: "pending" | "synced" | "failed";
	error: string | null;
	attempts: number;
	updatedAt: string;
};

/** Secret-authorized attendee view. Host listings redact token; never publish this object. */
export type WaitlistEntry = {
	id: string;
	eventTypeId: string;
	hostId: string;
	eventName: string;
	start: string;
	end: string;
	timezone: string;
	name: string;
	email: string;
	status:
		| "unverified"
		| "waiting"
		| "offered"
		| "accepted"
		| "cancelled"
		| "expired";
	token: string;
	expiresAt: string;
	offerExpiresAt: string | null;
	bookingId: string | null;
	createdAt: string;
	verifiedAt: string | null;
};
/** Storage shape with Date timestamps and private delivery bookkeeping. */
export type WaitlistRecord = Omit<
	WaitlistEntry,
	"start" | "end" | "expiresAt" | "offerExpiresAt" | "createdAt" | "verifiedAt"
> & {
	start: Date;
	end: Date;
	expiresAt: Date;
	offerExpiresAt: Date | null;
	createdAt: Date;
	verifiedAt: Date | null;
	offerDelivered: boolean;
};

import { z } from "zod";

export const timezoneSchema = z
	.string()
	.min(1)
	.max(100)
	.refine((zone) => {
		try {
			new Intl.DateTimeFormat("en", { timeZone: zone }).format();
			return true;
		} catch {
			return false;
		}
	}, "Invalid timezone");

export const calendarDateSchema = z.iso.date();
const timeSchema = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/);
const endTimeSchema = z.union([timeSchema, z.literal("24:00")]);
const intervalSchema = z
	.object({ start: timeSchema, end: endTimeSchema })
	.refine(
		({ start, end }) => start < end,
		"Availability must end after it starts",
	);
export const weeklyAvailabilitySchema = z
	.object({
		dayOfWeek: z.number().int().min(0).max(6),
		start: timeSchema,
		end: endTimeSchema,
	})
	.refine(
		({ start, end }) => start < end,
		"Availability must end after it starts",
	);
export const dateOverrideSchema = z.object({
	date: calendarDateSchema,
	intervals: z.array(intervalSchema).max(24),
});
const limitSchema = z.number().int().positive().max(1_000_000).optional();
export const bookingLimitsSchema = z.object({
	perHour: limitSchema,
	perDay: limitSchema,
	perWeek: limitSchema,
	total: limitSchema,
});

export const createEventTypeSchema = z
	.object({
		slug: z
			.string()
			.min(1)
			.max(100)
			.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
		name: z.string().trim().min(1).max(200),
		description: z.string().max(5000).default(""),
		location: z.string().max(500).default(""),
		duration: z.number().int().min(1).max(1440),
		capacity: z.number().int().min(1).max(10000).default(1),
		waitlistEnabled: z.boolean().default(false),
		price: z
			.number()
			.int()
			.nonnegative()
			.max(Number.MAX_SAFE_INTEGER)
			.nullish(),
		currency: z
			.string()
			.regex(/^[A-Z]{3}$/)
			.nullish(),
		timezone: timezoneSchema,
		weeklyAvailability: z.array(weeklyAvailabilitySchema).max(168).default([]),
		dateOverrides: z
			.array(dateOverrideSchema)
			.max(366)
			.default([])
			.refine(
				(overrides) =>
					new Set(overrides.map((override) => override.date)).size ===
					overrides.length,
				"Only one override is allowed per date",
			),
		limits: bookingLimitsSchema.default({}),
		active: z.boolean().default(true),
	})
	.refine(({ price, currency }) => (price != null) === (currency != null), {
		message: "Supply price and currency together",
		path: ["currency"],
	});

export const createBookingSchema = z.object({
	start: z.iso.datetime({ offset: true }),
	timezone: timezoneSchema,
	name: z.string().trim().min(1).max(200),
	email: z
		.email()
		.max(320)
		.transform((value) => value.toLowerCase()),
});
export const availabilityQuerySchema = z.object({
	date: calendarDateSchema,
	timezone: timezoneSchema,
});
export const rescheduleBookingSchema = z.object({
	start: z.iso.datetime({ offset: true }),
	timezone: timezoneSchema,
});
export const listBookingsQuerySchema = z.object({
	period: z.enum(["upcoming", "past", "all"]).default("upcoming"),
	eventTypeId: z.string().min(1).optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const eventFacts = { eventTypeId: z.string(), hostId: z.string() };
const hostFacts = { hostId: z.string().optional() };
const bookingFacts = { bookingId: z.string(), hostId: z.string() };

export const calendarPermissions = definePermissions("calendar", {
	eventType: {
		list: permission(z.object(hostFacts)),
		read: permission(z.object({ ...eventFacts, public: z.boolean() })),
		create: permission(z.object(hostFacts)),
		update: permission(z.object(eventFacts)),
		delete: permission(z.object(eventFacts)),
	},
	connection: {
		list: permission(z.object(hostFacts)),
		connect: permission(z.object(hostFacts)),
		manage: permission(
			z.object({
				hostId: z.string(),
				connectionId: z.string().optional(),
			}),
		),
	},
	sync: {
		retry: permission(z.object({ hostId: z.string(), syncId: z.string() })),
	},
	payment: { webhook: permission(z.object({})) },
	availability: { read: permission(z.object(eventFacts)) },
	booking: {
		list: permission(z.object(hostFacts)),
		create: permission(z.object(eventFacts)),
		read: permission(z.object({ ...bookingFacts, tokenValid: z.boolean() })),
		cancel: permission(z.object({ ...bookingFacts, tokenValid: z.boolean() })),
		reschedule: permission(
			z.object({ ...bookingFacts, tokenValid: z.boolean() }),
		),
		confirmPayment: permission(z.object(bookingFacts)),
		remind: permission(z.object(bookingFacts)),
	},
});

"use client";
import { useEffect, useRef } from "react";
import type { Booking } from "../../types";

const checkoutKey = (eventTypeId: string) =>
	`btst:calendar:checkout:${eventTypeId}`;

/** Keep the private management link available when hosted checkout returns to the public booking page. */
export function openCalendarCheckout(booking: Booking, redirectUrl: string) {
	sessionStorage.setItem(checkoutKey(booking.eventTypeId), booking.cancelToken);
	window.location.assign(redirectUrl);
}

/** Consume the token once; the management route then owns it in its URL. */
export function takeCalendarCheckoutToken(eventTypeId: string) {
	try {
		const key = checkoutKey(eventTypeId);
		const token = sessionStorage.getItem(key);
		if (token) sessionStorage.removeItem(key);
		return token;
	} catch {
		return null;
	}
}

/** Check a pending checkout response against the still-mounted booking context. */
export function useCheckoutContext(context: string) {
	const current = useRef<string | null>(context);
	current.current = context;
	useEffect(() => {
		current.current = context;
		return () => {
			current.current = null;
		};
	}, [context]);
	return () => current.current === context;
}

"use client";

import { useState } from "react";
import { PermissionAccess, useIdentity } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { calendarPermissions } from "../../permissions";
import type { CalendarConnection } from "../../types";
import {
	useCalendarConnections,
	useConnectedCalendarOptions,
	useConnectCalendarProvider,
	useDisconnectCalendarProvider,
	useRetryCalendarSync,
	useSelectConnectedCalendar,
} from "@btst/plugin-calendar/client/hooks";
import { calendarSelectClass, Field } from "./shared";

const providerNames = { google: "Google", microsoft: "Microsoft" } as const;

export function CalendarConnectionsSection() {
	const { data, isPending, error, refetch, isFetching } =
		useCalendarConnections();
	const { identity } = useIdentity();
	const connect = useConnectCalendarProvider();
	const retry = useRetryCalendarSync();
	if (isPending) return <p role="status">Loading calendar connections…</p>;
	if (error)
		return (
			<p role="alert" className="text-destructive">
				{error.message}
			</p>
		);
	if (
		!data ||
		!identity ||
		(data.providers.length === 0 &&
			data.connections.length === 0 &&
			data.sync.length === 0)
	)
		return null;
	return (
		<section
			aria-labelledby="calendar-connections-heading"
			className="space-y-4"
		>
			<div>
				<div className="flex flex-wrap items-center justify-between gap-2">
					<h2
						id="calendar-connections-heading"
						className="text-xl font-semibold"
					>
						Connected calendars
					</h2>
					<Button
						className="min-h-11"
						variant="outline"
						disabled={isFetching}
						onClick={() => void refetch()}
					>
						Refresh connections
					</Button>
				</div>
				<p className="mt-1 text-sm text-muted-foreground">
					Authorize an account through this application, then connect and choose
					a calendar. Busy times block bookings; confirmed bookings synchronize
					automatically.
				</p>
			</div>
			{connect.error && (
				<p role="alert" className="text-destructive">
					{connect.error.message}
				</p>
			)}
			<PermissionAccess permission={calendarPermissions.connection.connect({})}>
				<div className="flex flex-wrap gap-2">
					{data.providers.map((provider) => (
						<Button
							key={provider}
							className="min-h-11"
							variant="outline"
							disabled={
								connect.isPending ||
								data.connections.some(
									(item) =>
										item.provider === provider &&
										item.status !== "disconnected",
								)
							}
							onClick={() => connect.mutate(provider)}
						>
							Connect {providerNames[provider]}
						</Button>
					))}
				</div>
			</PermissionAccess>
			{data.connections
				.filter((connection) => connection.status !== "disconnected")
				.map((connection) => (
					<Connection
						key={`${connection.id}:${connection.calendarId}:${connection.status}`}
						connection={connection}
						hostId={identity.id}
						onRefresh={() => void refetch()}
					/>
				))}
			{data.sync.length > 0 && (
				<div className="space-y-3">
					<h3 className="font-medium">Booking synchronization</h3>
					{retry.error && (
						<p role="alert" className="text-destructive">
							{retry.error.message}
						</p>
					)}
					<ul className="divide-y rounded-lg border">
						{data.sync.map((sync) => (
							<li
								key={sync.id}
								className="space-y-2 p-4"
								data-testid="calendar-sync-state"
							>
								<div className="flex flex-wrap items-baseline justify-between gap-2">
									<p className="break-all text-sm">Booking {sync.bookingId}</p>
									<span className="text-sm font-medium">
										{sync.state === "synced"
											? "Synced"
											: sync.state === "failed"
												? "Sync failed"
												: "Sync pending"}
									</span>
								</div>
								<p className="text-sm text-muted-foreground">
									{data.connections.find(
										(connection) => connection.id === sync.connectionId,
									)?.label ?? "Disconnected calendar"}{" "}
									· {sync.attempts}{" "}
									{sync.attempts === 1 ? "attempt" : "attempts"}
								</p>
								{sync.error && (
									<p className="text-sm text-destructive">{sync.error}</p>
								)}
								{sync.state !== "synced" && (
									<PermissionAccess
										permission={calendarPermissions.sync.retry({
											hostId: identity.id,
											syncId: sync.id,
										})}
									>
										<Button
											className="min-h-11"
											variant="outline"
											disabled={retry.isPending}
											onClick={() => retry.mutate(sync.id)}
										>
											Retry synchronization
											<span className="sr-only">
												{" "}
												for booking {sync.bookingId}
											</span>
										</Button>
									</PermissionAccess>
								)}
							</li>
						))}
					</ul>
				</div>
			)}
		</section>
	);
}

function Connection({
	connection,
	hostId,
	onRefresh,
}: {
	connection: CalendarConnection;
	hostId: string;
	onRefresh: () => void;
}) {
	const disconnecting = connection.status === "disconnecting";
	const {
		data: calendars,
		error: calendarsError,
		isPending,
	} = useConnectedCalendarOptions(connection.id, !disconnecting);
	const select = useSelectConnectedCalendar();
	const disconnect = useDisconnectCalendarProvider();
	const [calendarId, setCalendarId] = useState(connection.calendarId ?? "");
	const error =
		(disconnecting ? null : calendarsError) ?? select.error ?? disconnect.error;
	return (
		<div className="space-y-4 rounded-lg border p-4 sm:p-5">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<div className="min-w-0">
					<h3 className="break-words font-medium">{connection.label}</h3>
					<p className="text-sm text-muted-foreground">
						{providerNames[connection.provider]} ·{" "}
						{connection.calendarName ??
							"Choose a calendar to enable synchronization"}
					</p>
				</div>
				<PermissionAccess
					permission={calendarPermissions.connection.manage({
						hostId,
						connectionId: connection.id,
					})}
				>
					<Button
						className="min-h-11"
						variant="outline"
						disabled={disconnect.isPending || select.isPending}
						onClick={() => {
							if (
								window.confirm(
									"Disconnect this calendar? Mirrored booking events will be removed before access is revoked. Local bookings will remain.",
								)
							)
								disconnect.mutate(connection.id, { onSettled: onRefresh });
						}}
					>
						{disconnecting ? "Retry disconnect" : "Disconnect"}
						<span className="sr-only"> {connection.label}</span>
					</Button>
				</PermissionAccess>
			</div>
			{error && (
				<p role="alert" className="text-destructive">
					{error.message}
				</p>
			)}
			{disconnecting ? (
				<p role="status" className="text-sm text-muted-foreground">
					Calendar access revocation is pending. Retry disconnect to finish.
				</p>
			) : isPending ? (
				<p role="status">Loading calendars…</p>
			) : (
				<PermissionAccess
					permission={calendarPermissions.connection.manage({
						hostId,
						connectionId: connection.id,
					})}
				>
					<form
						className="flex flex-wrap items-end gap-3"
						onSubmit={(event) => {
							event.preventDefault();
							select.mutate({ id: connection.id, calendarId });
						}}
					>
						<div className="min-w-0 flex-1">
							<Field
								label={`Calendar for ${connection.label}`}
								id={`calendar-connection-${connection.id}`}
							>
								<select
									id={`calendar-connection-${connection.id}`}
									className={calendarSelectClass}
									value={calendarId}
									onChange={(event) => setCalendarId(event.target.value)}
									required
								>
									<option value="">Choose a calendar</option>
									{calendars?.map((calendar) => (
										<option key={calendar.id} value={calendar.id}>
											{calendar.name}
										</option>
									))}
								</select>
							</Field>
						</div>
						<Button
							type="submit"
							className="min-h-11"
							disabled={
								!calendarId ||
								select.isPending ||
								disconnect.isPending ||
								calendarId === connection.calendarId
							}
						>
							Save calendar
						</Button>
					</form>
				</PermissionAccess>
			)}
		</div>
	);
}

"use client";

import { Button } from "@/components/ui/button";
import { generateBookingInvite } from "@btst/plugin-calendar/client/hooks";
import type { Booking } from "../../types";

export function CalendarInviteDownload({
	booking,
}: {
	booking: Omit<Booking, "cancelToken">;
}) {
	return (
		<Button className="min-h-11" variant="outline" asChild>
			<a
				download="booking.ics"
				href={`data:text/calendar;charset=utf-8,${encodeURIComponent(generateBookingInvite(booking))}`}
			>
				Download calendar invite (.ics)
			</a>
		</Button>
	);
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { calendarPermissions } from "../../permissions";
import { CalendarError, CalendarLoading, CalendarNotFound } from "./shared";

const Dashboard = lazy(() =>
	import("./pages/dashboard").then((m) => ({
		default: m.CalendarDashboardPage,
	})),
);
const Editor = lazy(() =>
	import("./pages/event-editor").then((m) => ({
		default: m.CalendarEventEditorPage,
	})),
);
const Booking = lazy(() =>
	import("./pages/booking").then((m) => ({ default: m.CalendarBookingPage })),
);
const Cancellation = lazy(() =>
	import("./pages/cancellation").then((m) => ({
		default: m.CalendarCancellationPage,
	})),
);
const Reschedule = lazy(() =>
	import("./pages/reschedule").then((m) => ({
		default: m.CalendarReschedulePage,
	})),
);

const Waitlist = lazy(() =>
	import("./pages/waitlist").then((m) => ({ default: m.CalendarWaitlistPage })),
);

const boundary = {
	ErrorComponent: CalendarError,
	LoadingComponent: CalendarLoading,
	NotFoundComponent: CalendarNotFound,
	onError: (error: Error) => console.error("[btst/calendar]", error),
};

export function CalendarDashboardPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/calendar"
			permission={calendarPermissions.eventType.list({})}
			PageComponent={Dashboard}
		/>
	);
}

export function CalendarEventEditorPageComponent({ id }: { id?: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={id ? `/calendar/events/${id}/edit` : "/calendar/events/new"}
			permission={id ? undefined : calendarPermissions.eventType.create({})}
			PageComponent={Editor}
			props={{ id }}
		/>
	);
}

export function CalendarBookingPageComponent({ slug }: { slug: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/book/${slug}`}
			PageComponent={Booking}
			props={{ slug }}
		/>
	);
}

export function CalendarCancellationPageComponent({
	token,
}: {
	token: string;
}) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/cancel/${token}`}
			PageComponent={Cancellation}
			props={{ token }}
		/>
	);
}

export function CalendarReschedulePageComponent({ token }: { token: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/reschedule/${token}`}
			PageComponent={Reschedule}
			props={{ token }}
		/>
	);
}

export function CalendarWaitlistPageComponent({ token }: { token: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/calendar/waitlist/${token}`}
			PageComponent={Waitlist}
			props={{ token }}
		/>
	);
}

"use client";

import { useEffect, useState, type FormEvent } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { BookingCheckout } from "../../../types";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarSlots,
	useCreateCalendarBooking,
	useJoinCalendarWaitlist,
	usePublicCalendarEvent,
} from "@btst/plugin-calendar/client/hooks";
import {
	CalendarPage,
	Field,
	formatCalendarTime,
	formatCalendarPrice,
} from "../shared";
import {
	openCalendarCheckout,
	takeCalendarCheckoutToken,
	useCheckoutContext,
} from "../checkout";
import { CalendarPayment } from "../payment";
import { CalendarInviteDownload } from "../invite-download";
import { CalendarTimePicker, calendarToday } from "../time-picker";

export function CalendarBookingPage({ slug }: { slug: string }) {
	const { data: event } = usePublicCalendarEvent(slug);
	const [timezone, setTimezone] = useState(event.timezone);
	const [date, setDate] = useState(() => calendarToday(event.timezone));
	const [start, setStart] = useState("");
	const [waitlistRequested, setWaitlistRequested] = useState<string>();
	const [checkoutError, setCheckoutError] = useState(false);
	const [confirmation, setConfirmation] = useState<BookingCheckout>();
	const slots = useCalendarSlots(slug, date, timezone);
	const create = useCreateCalendarBooking();
	const join = useJoinCalendarWaitlist();
	const { Link, resolve, navigate } =
		usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	useEffect(() => {
		const localZone = Intl.DateTimeFormat().resolvedOptions().timeZone;
		setTimezone(localZone);
		setDate(calendarToday(localZone));
	}, []);
	useEffect(() => {
		if (confirmation) return;
		const token = takeCalendarCheckoutToken(event.id);
		if (token) void navigate("calendar", "cancel", token);
	}, [event.id, navigate, confirmation]);
	const isCurrentCheckout = useCheckoutContext(
		JSON.stringify([event.id, slug]),
	);
	const chosenSlot = [
		...(slots.data?.slots ?? []),
		...(event.waitlistEnabled ? (slots.data?.waitlistSlots ?? []) : []),
	].find((slot) => slot.start === start);
	const joiningWaitlist = chosenSlot?.remaining === 0;
	const pending = create.isPending || join.isPending;
	const error = joiningWaitlist ? join.error : create.error;
	const submit = async (e: FormEvent<HTMLFormElement>) => {
		e.preventDefault();
		if (!chosenSlot) return;
		const data = new FormData(e.currentTarget);
		try {
			const input = {
				slug,
				start,
				timezone,
				name: String(data.get("name")),
				email: String(data.get("email")),
			};
			if (joiningWaitlist) {
				await join.mutateAsync(input);
				if (isCurrentCheckout()) setWaitlistRequested(event.id);
				return;
			}
			const booking = await create.mutateAsync(input);
			if (!isCurrentCheckout()) return;
			setConfirmation(booking);
			if (booking.checkout?.redirectUrl) {
				try {
					openCalendarCheckout(booking, booking.checkout.redirectUrl);
				} catch {
					setCheckoutError(true);
				}
			}
		} catch {
			// The mutation exposes its error beside the booking form.
		}
	};
	if (waitlistRequested === event.id)
		return (
			<CalendarPage>
				<section aria-live="polite" className="max-w-xl space-y-4">
					<h1 className="text-2xl font-semibold sm:text-3xl">
						Check your email
					</h1>
					<p>
						If this request is eligible, you will receive a private link to
						verify your email and manage your waitlist entry.
					</p>
					<p>
						Joining the waitlist does not confirm a booking or charge you. If a
						place opens, you must accept the time-limited offer.
					</p>
				</section>
			</CalendarPage>
		);
	if (confirmation)
		return (
			<CalendarPage>
				<section aria-live="polite" className="max-w-xl space-y-4">
					<h1 className="text-2xl font-semibold sm:text-3xl">
						{confirmation.status === "pending_payment"
							? "Booking awaiting payment"
							: "Booking confirmed"}
					</h1>
					<CalendarPayment booking={confirmation} />
					{checkoutError && (
						<p role="alert">
							Browser storage is unavailable. Save your private booking link and
							enable browser storage before continuing payment.
						</p>
					)}
					<p>{confirmation.eventName}</p>
					<p>
						{formatCalendarTime(confirmation.start, confirmation.timezone)} (
						{confirmation.timezone})
					</p>
					{event.location && (
						<p className="break-words">Location: {event.location}</p>
					)}
					<p>Save this link to manage your booking.</p>
					<CalendarInviteDownload booking={confirmation} />
					<Button className="min-h-11" variant="outline" asChild>
						<Link
							href={
								resolve("calendar", "cancel", confirmation.cancelToken).href
							}
						>
							Manage or cancel booking
						</Link>
					</Button>
				</section>
			</CalendarPage>
		);
	return (
		<CalendarPage>
			<header className="max-w-2xl space-y-2">
				<h1 className="break-words text-2xl font-semibold sm:text-3xl">
					{event.name}
				</h1>
				<p className="text-muted-foreground">
					{event.duration} minutes ·{" "}
					{event.capacity === 1
						? "1:1 booking"
						: `Up to ${event.capacity} attendees`}
				</p>
				{event.description && (
					<p className="whitespace-pre-wrap break-words">{event.description}</p>
				)}
				{event.location && (
					<p className="break-words">Location: {event.location}</p>
				)}
				{(event.price ?? 0) > 0 && event.currency && (
					<p>
						Price: {formatCalendarPrice(event.price!, event.currency)}. Payment
						is required to confirm your booking.
					</p>
				)}
			</header>
			<div className="grid min-w-0 gap-8 lg:grid-cols-2">
				<CalendarTimePicker
					page="calendarBooking"
					date={date}
					timezone={timezone}
					start={start}
					onDate={setDate}
					onTimezone={setTimezone}
					onStart={setStart}
					slots={slots}
					capacity={event.capacity}
					waitlistEnabled={event.waitlistEnabled}
				/>
				<form
					onSubmit={submit}
					className="min-w-0 space-y-5 rounded-lg border p-4 sm:p-6"
				>
					<h2 className="text-xl font-semibold">Your details</h2>
					{chosenSlot ? (
						<p className="text-sm">
							{formatCalendarTime(chosenSlot.start, timezone)} ({timezone})
							{joiningWaitlist && " · Full — join the waitlist for this time"}
						</p>
					) : (
						<p className="text-sm text-muted-foreground">
							{event.waitlistEnabled
								? "Select a time to book or join its waitlist."
								: "Select an available time to confirm your booking."}
						</p>
					)}
					<Field id="calendar-name" label="Your name">
						<Input
							id="calendar-name"
							className="min-h-11"
							name="name"
							autoComplete="name"
							required
							maxLength={200}
						/>
					</Field>
					<Field id="calendar-email" label="Email">
						<Input
							id="calendar-email"
							className="min-h-11"
							name="email"
							type="email"
							autoComplete="email"
							required
							maxLength={320}
						/>
					</Field>
					{joiningWaitlist && (
						<p className="text-sm text-muted-foreground">
							Verify your email using the private link we send you. A waitlist
							entry does not reserve a place or charge you.
						</p>
					)}
					{error && (
						<p role="alert" className="text-destructive">
							{error.message}
						</p>
					)}
					<Button
						className="min-h-11 w-full"
						type="submit"
						disabled={!chosenSlot || pending || slots.isFetching}
					>
						{pending
							? joiningWaitlist
								? "Requesting waitlist…"
								: "Reserving booking…"
							: joiningWaitlist
								? "Join waitlist"
								: (event.price ?? 0) > 0
									? "Reserve pending payment"
									: "Confirm booking"}
					</Button>
				</form>
			</div>
		</CalendarPage>
	);
}

"use client";

import { Button } from "@/components/ui/button";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import { CalendarPayment } from "../payment";
import { CalendarInviteDownload } from "../invite-download";
import { useCalendarBooking, useCancelCalendarBooking } from "@btst/plugin-calendar/client/hooks";
import { CalendarPage, formatCalendarTime } from "../shared";

export function CalendarCancellationPage({ token }: { token: string }) {
	const { data, refetch, isFetching } = useCalendarBooking(token);
	const cancel = useCancelCalendarBooking();
	const booking = cancel.data ?? data;
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	return (
		<CalendarPage>
			<section className="max-w-xl space-y-5" aria-live="polite">
				<h1 className="text-2xl font-semibold sm:text-3xl">
					{booking.status === "cancelled"
						? "Booking cancelled"
						: "Manage booking"}
				</h1>
				<h2 className="break-words text-xl">{booking.eventName}</h2>
				<p>
					{formatCalendarTime(booking.start, booking.timezone)} (
					{booking.timezone})
				</p>
				{booking.status === "pending_payment" && (
					<>
						<CalendarPayment booking={booking} />
						<Button
							className="min-h-11"
							variant="outline"
							disabled={isFetching}
							onClick={() => void refetch()}
						>
							Check payment status
						</Button>
					</>
				)}
				<CalendarInviteDownload booking={booking} />
				{booking.status === "cancelled" ? (
					<p>Your booking has been cancelled.</p>
				) : (
					<>
						{Date.parse(booking.start) > Date.now() && (
							<Button className="min-h-11" variant="outline" asChild>
								<Link href={resolve("calendar", "reschedule", token).href}>
									Reschedule booking
								</Link>
							</Button>
						)}
						<p>Cancel this booking if you can no longer attend.</p>
						{cancel.error && (
							<p role="alert" className="text-destructive">
								{cancel.error.message}
							</p>
						)}
						<Button
							className="min-h-11"
							variant="destructive"
							disabled={cancel.isPending}
							onClick={() => cancel.mutate(token)}
						>
							{cancel.isPending ? "Cancelling booking…" : "Cancel booking"}
						</Button>
					</>
				)}
			</section>
		</CalendarPage>
	);
}

"use client";

import { useState } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { calendarPermissions } from "../../../permissions";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarBookings,
	useCalendarWaitlist,
	useCalendarEvents,
	useCancelHostCalendarBooking,
	useDeleteCalendarEvent,
} from "@btst/plugin-calendar/client/hooks";
import { CalendarPage, formatCalendarTime } from "../shared";
import { CalendarInviteDownload } from "../invite-download";
import { CalendarConnectionsSection } from "../connections";

export function CalendarDashboardPage() {
	const { data: events } = useCalendarEvents();
	const remove = useDeleteCalendarEvent();
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	useRegisterPageAIContext({
		routeName: "calendar-admin",
		pageDescription: JSON.stringify({
			page: "Read-only Calendar dashboard summary. No mutation tools are available.",
			eventTypes: events.length,
			acceptingBookings: events.filter((event) => event.active).length,
		}),
	});
	return (
		<CalendarPage>
			<header className="flex flex-wrap items-center justify-between gap-4">
				<div>
					<h1 className="text-2xl font-semibold sm:text-3xl">Calendar</h1>
					<p className="mt-1 text-muted-foreground">
						Manage event types and scheduled bookings.
					</p>
				</div>
				<PermissionAccess permission={calendarPermissions.eventType.create({})}>
					<Button className="min-h-11" asChild>
						<Link href={resolve("calendar", "events", "new").href}>
							New event type
						</Link>
					</Button>
				</PermissionAccess>
			</header>
			<PermissionAccess permission={calendarPermissions.connection.list({})}>
				<CalendarConnectionsSection />
			</PermissionAccess>
			<section aria-labelledby="calendar-events-heading" className="space-y-4">
				<h2 id="calendar-events-heading" className="text-xl font-semibold">
					Event types
				</h2>
				{remove.error && (
					<p role="alert" className="text-destructive">
						{remove.error.message}
					</p>
				)}
				{events.length === 0 ? (
					<p className="rounded-lg border p-6 text-muted-foreground">
						No event types yet. Create one to set your availability and share a
						booking page.
					</p>
				) : (
					<ul className="divide-y rounded-lg border">
						{events.map((event) => (
							<li
								key={event.id}
								className="flex min-w-0 flex-wrap items-center justify-between gap-4 p-4 sm:p-5"
							>
								<div className="min-w-0">
									<h3 className="break-words font-medium">{event.name}</h3>
									<p className="text-sm text-muted-foreground">
										{event.duration} minutes ·{" "}
										{event.capacity === 1
											? "1:1"
											: `Up to ${event.capacity} attendees`}{" "}
										· {event.active ? "Accepting bookings" : "Paused"}
									</p>
								</div>
								<div className="flex flex-wrap gap-2">
									{event.active && (
										<Button className="min-h-11" variant="outline" asChild>
											<Link href={resolve("calendar", "book", event.slug).href}>
												Booking page
											</Link>
										</Button>
									)}
									<PermissionAccess
										permission={calendarPermissions.eventType.update({
											eventTypeId: event.id,
											hostId: event.hostId,
										})}
									>
										<Button className="min-h-11" variant="outline" asChild>
											<Link
												href={
													resolve("calendar", "events", event.id, "edit").href
												}
											>
												Edit<span className="sr-only"> {event.name}</span>
											</Link>
										</Button>
									</PermissionAccess>
									<PermissionAccess
										permission={calendarPermissions.eventType.delete({
											eventTypeId: event.id,
											hostId: event.hostId,
										})}
									>
										<Button
											className="min-h-11"
											variant="ghost"
											disabled={remove.isPending}
											onClick={() => {
												if (
													window.confirm(
														`Delete ${event.name}? Existing bookings must be cancelled first.`,
													)
												)
													remove.mutate(event.id);
											}}
										>
											Delete<span className="sr-only"> {event.name}</span>
										</Button>
									</PermissionAccess>
								</div>
							</li>
						))}
					</ul>
				)}
			</section>
			<PermissionAccess permission={calendarPermissions.booking.list({})}>
				{events.some((event) => event.waitlistEnabled) && <WaitlistSection />}
				<BookingsSection />
			</PermissionAccess>
		</CalendarPage>
	);
}

function BookingsSection() {
	const [period, setPeriod] = useState<"upcoming" | "past">("upcoming");
	const { data: bookings } = useCalendarBookings(period);
	const cancel = useCancelHostCalendarBooking();
	return (
		<section aria-labelledby="calendar-bookings-heading" className="space-y-4">
			<div className="flex flex-wrap items-center justify-between gap-3">
				<h2 id="calendar-bookings-heading" className="text-xl font-semibold">
					Bookings
				</h2>
				<div className="flex gap-2" aria-label="Booking period">
					{(["upcoming", "past"] as const).map((value) => (
						<Button
							key={value}
							className="min-h-11"
							variant={period === value ? "default" : "outline"}
							aria-pressed={period === value}
							onClick={() => setPeriod(value)}
						>
							{value === "upcoming" ? "Upcoming" : "Past"}
						</Button>
					))}
				</div>
			</div>
			{cancel.error && (
				<p role="alert" className="text-destructive">
					{cancel.error.message}
				</p>
			)}
			{bookings.length === 0 ? (
				<p className="rounded-lg border p-6 text-muted-foreground">
					No {period} bookings.
				</p>
			) : (
				<ul className="divide-y rounded-lg border">
					{bookings.map((booking) => (
						<li key={booking.id} className="space-y-1 p-4 sm:p-5">
							<div className="flex flex-wrap items-baseline justify-between gap-2">
								<h3 className="break-words font-medium">{booking.eventName}</h3>
								<span className="text-sm">
									{booking.status === "cancelled"
										? "Cancelled"
										: booking.status === "pending_payment"
											? "Payment pending"
											: "Confirmed"}
								</span>
							</div>
							<p>
								{formatCalendarTime(booking.start, booking.timezone)} (
								{booking.timezone})
							</p>
							<p className="break-words text-sm text-muted-foreground">
								{booking.name} · {booking.email}
							</p>
							<CalendarInviteDownload booking={booking} />
							{booking.status !== "cancelled" && (
								<PermissionAccess
									permission={calendarPermissions.booking.cancel({
										bookingId: booking.id,
										hostId: booking.hostId,
										tokenValid: false,
									})}
								>
									<Button
										className="min-h-11"
										variant="outline"
										disabled={cancel.isPending}
										onClick={() => cancel.mutate(booking.id)}
									>
										Cancel booking
										<span className="sr-only"> for {booking.name}</span>
									</Button>
								</PermissionAccess>
							)}
						</li>
					))}
				</ul>
			)}
		</section>
	);
}

function WaitlistSection() {
	const { data: entries } = useCalendarWaitlist();
	return (
		<section aria-labelledby="calendar-waitlist-heading" className="space-y-4">
			<h2 id="calendar-waitlist-heading" className="text-xl font-semibold">
				Waitlist
			</h2>
			<p className="text-sm text-muted-foreground">
				Verified attendees receive offers in order. An offer holds a place until
				it is accepted, cancelled or expires.
			</p>
			{entries.length === 0 ? (
				<p className="rounded-lg border p-6 text-muted-foreground">
					No waitlist entries.
				</p>
			) : (
				<ul className="divide-y rounded-lg border">
					{entries.map((entry) => (
						<li key={entry.id} className="space-y-1 p-4 sm:p-5">
							<div className="flex flex-wrap items-baseline justify-between gap-2">
								<h3 className="break-words font-medium">{entry.eventName}</h3>
								<span className="text-sm">
									{entry.status === "unverified"
										? "Email verification pending"
										: entry.status === "offered"
											? "Offer sent"
											: entry.status === "waiting"
												? "Waiting"
												: entry.status === "accepted"
													? "Accepted"
													: entry.status === "cancelled"
														? "Cancelled"
														: "Expired"}
								</span>
							</div>
							<p>
								{formatCalendarTime(entry.start, entry.timezone)} (
								{entry.timezone})
							</p>
							<p className="break-words text-sm text-muted-foreground">
								{entry.name} · {entry.email}
							</p>
							{entry.offerExpiresAt && entry.status === "offered" && (
								<p className="text-sm">
									Offer expires{" "}
									{formatCalendarTime(entry.offerExpiresAt, entry.timezone)} (
									{entry.timezone})
								</p>
							)}
						</li>
					))}
				</ul>
			)}
		</section>
	);
}

"use client";

import { useId, useState, type FormEvent } from "react";
import { PermissionRouteAccess } from "@btst/stack/client/components";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { calendarPermissions } from "../../../permissions";
import { createEventTypeSchema } from "../../../schemas";
import type { CalendarEventInput } from "@btst/plugin-calendar/query-keys";
import type { TimeInterval } from "../../../types";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarEvent,
	useCreateCalendarEvent,
	useUpdateCalendarEvent,
} from "@btst/plugin-calendar/client/hooks";
import {
	CalendarLoading,
	CalendarPage,
	Field,
	calendarSelectClass,
} from "../shared";

const days = [
	"Sunday",
	"Monday",
	"Tuesday",
	"Wednesday",
	"Thursday",
	"Friday",
	"Saturday",
];
const emptyEvent: CalendarEventInput = {
	name: "",
	slug: "",
	description: "",
	location: "",
	duration: 30,
	capacity: 1,
	waitlistEnabled: false,
	timezone: "UTC",
	active: true,
	limits: {},
	dateOverrides: [],
	weeklyAvailability: [1, 2, 3, 4, 5].map((dayOfWeek) => ({
		dayOfWeek,
		start: "09:00",
		end: "17:00",
	})),
};

export function CalendarEventEditorPage({ id }: { id?: string }) {
	return id ? (
		<ExistingEventEditor id={id} />
	) : (
		<EventForm initial={emptyEvent} />
	);
}

function ExistingEventEditor({ id }: { id: string }) {
	const { data: event } = useCalendarEvent(id);
	return (
		<PermissionRouteAccess
			permission={calendarPermissions.eventType.update({
				eventTypeId: id,
				hostId: event.hostId,
			})}
			LoadingComponent={CalendarLoading}
		>
			<EventForm
				key={id}
				id={id}
				initial={createEventTypeSchema.parse(event)}
			/>
		</PermissionRouteAccess>
	);
}

function IntervalFields({
	value,
	onChange,
	label,
}: {
	value: TimeInterval;
	onChange: (value: TimeInterval) => void;
	label: string;
}) {
	const endHintId = useId();
	return (
		<div className="grid min-w-0 grid-cols-2 gap-3">
			<Input
				className="min-h-11"
				type="time"
				required
				aria-label={`${label} start`}
				value={value.start}
				onChange={(e) => onChange({ ...value, start: e.target.value })}
			/>
			<div className="min-w-0 space-y-1">
				<Input
					className="min-h-11"
					type="text"
					pattern="([01][0-9]|2[0-3]):[0-5][0-9]|24:00"
					maxLength={5}
					required
					aria-label={`${label} end`}
					aria-describedby={endHintId}
					value={value.end}
					onChange={(e) => onChange({ ...value, end: e.target.value })}
				/>
				<p id={endHintId} className="text-sm text-muted-foreground">
					HH:mm, up to 24:00.
				</p>
			</div>
		</div>
	);
}

function EventForm({
	id,
	initial,
}: {
	id?: string;
	initial: CalendarEventInput;
}) {
	const [form, setForm] = useState(initial);
	const [validationError, setValidationError] = useState("");
	const create = useCreateCalendarEvent();
	const update = useUpdateCalendarEvent();
	const { Link, navigate, resolve } =
		usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	const pending = create.isPending || update.isPending;
	const error =
		validationError || create.error?.message || update.error?.message;
	const submit = async (e: FormEvent<HTMLFormElement>) => {
		e.preventDefault();
		const parsed = createEventTypeSchema.safeParse(form);
		if (!parsed.success) {
			setValidationError(
				parsed.error.issues[0]?.message ??
					"Check the event details and availability.",
			);
			return;
		}
		setValidationError("");
		try {
			if (id) await update.mutateAsync({ id, data: parsed.data });
			else await create.mutateAsync(parsed.data);
			void navigate("calendar");
		} catch {
			// The mutation exposes its validation or authorization error in the form.
		}
	};
	return (
		<CalendarPage>
			<header className="space-y-3">
				<Link
					className="inline-flex min-h-11 items-center underline underline-offset-4"
					href={resolve("calendar").href}
				>
					Back to calendar
				</Link>
				<h1 className="text-2xl font-semibold sm:text-3xl">
					{id ? "Edit event type" : "New event type"}
				</h1>
			</header>
			<form onSubmit={submit} className="space-y-8">
				<fieldset
					disabled={pending}
					className="grid min-w-0 gap-5 sm:grid-cols-2"
				>
					<legend className="mb-4 text-xl font-semibold">Event details</legend>
					<Field id="calendar-event-name" label="Event name">
						<Input
							id="calendar-event-name"
							className="min-h-11"
							required
							maxLength={200}
							value={form.name}
							onChange={(e) => setForm({ ...form, name: e.target.value })}
						/>
					</Field>
					<Field
						id="calendar-event-slug"
						label="Booking page slug"
						hint="Use lowercase letters, numbers and hyphens."
					>
						<Input
							id="calendar-event-slug"
							className="min-h-11"
							required
							pattern="[a-z0-9]+(-[a-z0-9]+)*"
							maxLength={100}
							value={form.slug}
							onChange={(e) => setForm({ ...form, slug: e.target.value })}
						/>
					</Field>
					<Field id="calendar-duration" label="Duration (minutes)">
						<Input
							id="calendar-duration"
							className="min-h-11"
							type="number"
							min={1}
							max={1440}
							step={1}
							list="calendar-durations"
							required
							value={form.duration}
							onChange={(e) =>
								setForm({ ...form, duration: Number(e.target.value) })
							}
						/>
						<datalist id="calendar-durations">
							{[15, 30, 45, 60].map((value) => (
								<option key={value} value={value} />
							))}
						</datalist>
					</Field>
					<Field
						id="calendar-capacity"
						label="Attendees per time slot"
						hint="Use 1 for 1:1 bookings, or a higher number for a group."
					>
						<Input
							id="calendar-capacity"
							className="min-h-11"
							type="number"
							min={1}
							max={10000}
							step={1}
							required
							value={form.capacity}
							onChange={(e) =>
								setForm({
									...form,
									capacity: Number(e.target.value),
									waitlistEnabled:
										Number(e.target.value) > 1 && form.waitlistEnabled,
								})
							}
						/>
					</Field>
					<label className="flex min-h-11 items-start gap-3 text-sm sm:col-span-2">
						<input
							type="checkbox"
							className="mt-0.5 h-5 w-5 accent-primary"
							disabled={form.capacity < 2}
							checked={form.waitlistEnabled ?? false}
							onChange={(e) =>
								setForm({ ...form, waitlistEnabled: e.target.checked })
							}
						/>
						<span>
							Enable waitlists for full group slots
							<span className="mt-1 block text-muted-foreground">
								Attendees verify their email, then receive an offer when a place
								opens.
							</span>
						</span>
					</label>
					<Field
						id="calendar-host-timezone"
						label="Host timezone"
						hint="Availability and booking limits use this timezone."
					>
						<Input
							id="calendar-host-timezone"
							className="min-h-11"
							required
							list="calendar-timezones"
							value={form.timezone}
							onChange={(e) => setForm({ ...form, timezone: e.target.value })}
						/>
						<datalist id="calendar-timezones">
							<option value="UTC" />
							{Intl.supportedValuesOf("timeZone").map((zone) => (
								<option key={zone} value={zone} />
							))}
						</datalist>
					</Field>
					<Field
						id="calendar-price"
						label="Price (minor currency units)"
						hint="Optional. For USD, 2500 means $25.00; zero or blank is free."
					>
						<Input
							id="calendar-price"
							className="min-h-11"
							type="number"
							min={0}
							max={Number.MAX_SAFE_INTEGER}
							step={1}
							value={form.price ?? ""}
							onChange={(e) =>
								setForm({
									...form,
									price: e.target.value === "" ? null : Number(e.target.value),
								})
							}
						/>
					</Field>
					<Field
						id="calendar-currency"
						label="Currency"
						hint="Three-letter uppercase code, supplied with the price, such as USD."
					>
						<Input
							id="calendar-currency"
							className="min-h-11"
							pattern="[A-Z]{3}"
							maxLength={3}
							value={form.currency ?? ""}
							onChange={(e) =>
								setForm({
									...form,
									currency:
										e.target.value === "" ? null : e.target.value.toUpperCase(),
								})
							}
						/>
					</Field>
					<Field id="calendar-location" label="Location">
						<Input
							id="calendar-location"
							className="min-h-11"
							maxLength={500}
							value={form.location}
							onChange={(e) => setForm({ ...form, location: e.target.value })}
						/>
					</Field>
					<div className="sm:col-span-2">
						<Field id="calendar-description" label="Description">
							<Textarea
								id="calendar-description"
								rows={3}
								maxLength={5000}
								value={form.description}
								onChange={(e) =>
									setForm({ ...form, description: e.target.value })
