							<select
								className={calendarSelectClass}
								aria-label={`Availability ${index + 1} day`}
								value={rule.dayOfWeek}
								onChange={(e) =>
									setForm({
										...form,
										weeklyAvailability: form.weeklyAvailability.map(
											(item, i) =>
												i === index
													? { ...item, dayOfWeek: Number(e.target.value) }
													: item,
										),
									})
								}
							>
								{days.map((day, value) => (
									<option key={day} value={value}>
										{day}
									</option>
								))}
							</select>
							<IntervalFields
								label={`Availability ${index + 1}`}
								value={rule}
								onChange={(value) =>
									setForm({
										...form,
										weeklyAvailability: form.weeklyAvailability.map(
											(item, i) => (i === index ? { ...item, ...value } : item),
										),
									})
								}
							/>
							<Button
								className="min-h-11"
								type="button"
								variant="ghost"
								aria-label={`Remove availability ${index + 1}`}
								onClick={() =>
									setForm({
										...form,
										weeklyAvailability: form.weeklyAvailability.filter(
											(_, i) => i !== index,
										),
									})
								}
							>
								Remove
							</Button>
						</div>
					))}
					<Button
						className="min-h-11"
						type="button"
						variant="outline"
						onClick={() =>
							setForm({
								...form,
								weeklyAvailability: [
									...form.weeklyAvailability,
									{ dayOfWeek: 1, start: "09:00", end: "17:00" },
								],
							})
						}
					>
						Add availability window
					</Button>
				</fieldset>
				<fieldset disabled={pending} className="min-w-0 space-y-4">
					<legend className="text-xl font-semibold">Date overrides</legend>
					<p className="text-sm text-muted-foreground">
						Override a date in the host timezone. Leave its time windows empty
						to block the whole day.
					</p>
					{form.dateOverrides.length === 0 && (
						<p className="text-sm">
							No date overrides. Weekly availability applies every week.
						</p>
					)}
					{form.dateOverrides.map((override, index) => (
						<div
							key={index}
							className="min-w-0 space-y-3 rounded-lg border p-4"
						>
							<div className="flex flex-wrap items-end gap-3">
								<div className="min-w-0 flex-1">
									<Field
										id={`calendar-override-${index}`}
										label="Override date"
									>
										<Input
											id={`calendar-override-${index}`}
											className="min-h-11"
											type="date"
											required
											value={override.date}
											onChange={(e) =>
												setForm({
													...form,
													dateOverrides: form.dateOverrides.map((item, i) =>
														i === index
															? { ...item, date: e.target.value }
															: item,
													),
												})
											}
										/>
									</Field>
								</div>
								<Button
									className="min-h-11"
									type="button"
									variant="ghost"
									aria-label={`Remove date override ${index + 1}`}
									onClick={() =>
										setForm({
											...form,
											dateOverrides: form.dateOverrides.filter(
												(_, i) => i !== index,
											),
										})
									}
								>
									Remove date
								</Button>
							</div>
							{override.intervals.length === 0 && (
								<p className="text-sm text-muted-foreground">
									Unavailable all day.
								</p>
							)}
							{override.intervals.map((interval, intervalIndex) => (
								<div
									key={intervalIndex}
									className="grid min-w-0 gap-3 sm:grid-cols-[minmax(0,1fr)_auto]"
								>
									<IntervalFields
										label={`Override ${index + 1} window ${intervalIndex + 1}`}
										value={interval}
										onChange={(value) =>
											setForm({
												...form,
												dateOverrides: form.dateOverrides.map((item, i) =>
													i === index
														? {
																...item,
																intervals: item.intervals.map((entry, j) =>
																	j === intervalIndex ? value : entry,
																),
															}
														: item,
												),
											})
										}
									/>
									<Button
										className="min-h-11"
										type="button"
										variant="ghost"
										aria-label={`Remove override ${index + 1} window ${intervalIndex + 1}`}
										onClick={() =>
											setForm({
												...form,
												dateOverrides: form.dateOverrides.map((item, i) =>
													i === index
														? {
																...item,
																intervals: item.intervals.filter(
																	(_, j) => j !== intervalIndex,
																),
															}
														: item,
												),
											})
										}
									>
										Remove window
									</Button>
								</div>
							))}
							<Button
								className="min-h-11"
								type="button"
								variant="outline"
								onClick={() =>
									setForm({
										...form,
										dateOverrides: form.dateOverrides.map((item, i) =>
											i === index
												? {
														...item,
														intervals: [
															...item.intervals,
															{ start: "09:00", end: "17:00" },
														],
													}
												: item,
										),
									})
								}
							>
								Add override window
							</Button>
						</div>
					))}
					<Button
						className="min-h-11"
						type="button"
						variant="outline"
						onClick={() =>
							setForm({
								...form,
								dateOverrides: [
									...form.dateOverrides,
									{ date: "", intervals: [] },
								],
							})
						}
					>
						Add date override
					</Button>
				</fieldset>
				<fieldset disabled={pending} className="min-w-0 space-y-4">
					<legend className="text-xl font-semibold">Booking limits</legend>
					<p className="text-sm text-muted-foreground">
						Leave a limit empty for no limit.
					</p>
					<div className="grid min-w-0 gap-4 sm:grid-cols-2 lg:grid-cols-4">
						{(
							[
								["perHour", "Max bookings per hour"],
								["perDay", "Max bookings per day"],
								["perWeek", "Max bookings per week"],
								["total", "Max bookings total"],
							] as const
						).map(([key, label]) => (
							<Field key={key} id={`calendar-limit-${key}`} label={label}>
								<Input
									id={`calendar-limit-${key}`}
									className="min-h-11"
									type="number"
									min={1}
									max={1000000}
									step={1}
									value={form.limits[key] ?? ""}
									onChange={(e) =>
										setForm({
											...form,
											limits: {
												...form.limits,
												[key]: e.target.value
													? Number(e.target.value)
													: undefined,
											},
										})
									}
								/>
							</Field>
						))}
					</div>
				</fieldset>
				{error && (
					<p role="alert" className="text-destructive">
						{error}
					</p>
				)}
				<Button className="min-h-11" type="submit" disabled={pending}>
					{pending
						? "Saving event type…"
						: id
							? "Save event type"
							: "Create event type"}
				</Button>
			</form>
		</CalendarPage>
	);
}

"use client";

import { useState } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import type { Booking } from "../../../types";
import {
	useCalendarBooking,
	useCalendarRescheduleSlots,
	useRescheduleCalendarBooking,
} from "@btst/plugin-calendar/client/hooks";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import { CalendarPage, formatCalendarTime } from "../shared";
import { CalendarTimePicker } from "../time-picker";
import { CalendarInviteDownload } from "../invite-download";

export function CalendarReschedulePage({ token }: { token: string }) {
	const { data: booking } = useCalendarBooking(token);
	return booking.status === "cancelled" ||
		Date.parse(booking.start) <= Date.now() ? (
		<CalendarPage>
			<h1 className="text-2xl font-semibold">Booking cannot be rescheduled</h1>
			<p>Only upcoming active bookings can be rescheduled.</p>
		</CalendarPage>
	) : (
		<RescheduleForm token={token} booking={booking} />
	);
}

function RescheduleForm({
	token,
	booking,
}: {
	token: string;
	booking: Booking;
}) {
	const [timezone, setTimezone] = useState(booking.timezone);
	const [date, setDate] = useState(() =>
		new Intl.DateTimeFormat("en-CA", {
			timeZone: booking.timezone,
			year: "numeric",
			month: "2-digit",
			day: "2-digit",
		}).format(new Date(booking.start)),
	);
	const [start, setStart] = useState("");
	const slots = useCalendarRescheduleSlots(token, date, timezone);
	const reschedule = useRescheduleCalendarBooking();
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	const chosen = slots.data?.slots.find((slot) => slot.start === start);
	const current = reschedule.data ?? booking;
	return (
		<CalendarPage>
			<header className="space-y-3">
				<h1 className="text-2xl font-semibold sm:text-3xl">
					{reschedule.data ? "Booking rescheduled" : "Reschedule booking"}
				</h1>
				<h2 className="break-words text-xl">{booking.eventName}</h2>
				<p aria-live="polite">
					{formatCalendarTime(current.start, current.timezone)} (
					{current.timezone})
				</p>
			</header>
			{reschedule.data ? (
				<section className="space-y-4" aria-live="polite">
					<p>
						{reschedule.data.status === "pending_payment"
							? "Your time has moved. Payment is still pending."
							: "Your booking has moved to the new time."}
					</p>
					<CalendarInviteDownload booking={reschedule.data} />
				</section>
			) : (
				<div className="max-w-xl space-y-5">
					<p>
						Your current time stays reserved until the new time is confirmed.
					</p>
					<CalendarTimePicker
						page="calendarReschedule"
						date={date}
						timezone={timezone}
						start={start}
						onDate={setDate}
						onTimezone={setTimezone}
						onStart={setStart}
						slots={slots}
					/>
					{reschedule.error && (
						<p role="alert" className="text-destructive">
							{reschedule.error.message}
						</p>
					)}
					<Button
						className="min-h-11"
						disabled={!chosen || reschedule.isPending || slots.isFetching}
						onClick={() => reschedule.mutate({ token, start, timezone })}
					>
						{reschedule.isPending ? "Moving booking…" : "Confirm new time"}
					</Button>
				</div>
			)}
			<Link
				className="inline-flex min-h-11 items-center underline underline-offset-4"
				href={resolve("calendar", "cancel", token).href}
			>
				Manage booking
			</Link>
		</CalendarPage>
	);
}

"use client";

import { useState } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import type { BookingCheckout } from "../../../types";
import { CALENDAR_PLUGIN_ID } from "../../constants";
import {
	useCalendarWaitlistEntry,
	useVerifyCalendarWaitlist,
	useCancelCalendarWaitlist,
	useAcceptCalendarWaitlistOffer,
} from "@btst/plugin-calendar/client/hooks";
import { CalendarPage, formatCalendarTime } from "../shared";
import { CalendarPayment } from "../payment";
import { CalendarInviteDownload } from "../invite-download";
import { openCalendarCheckout, useCheckoutContext } from "../checkout";

export function CalendarWaitlistPage({ token }: { token: string }) {
	const { data: entry, refetch, isFetching } = useCalendarWaitlistEntry(token);
	const verify = useVerifyCalendarWaitlist();
	const cancel = useCancelCalendarWaitlist();
	const accept = useAcceptCalendarWaitlistOffer();
	const [confirmation, setConfirmation] = useState<{
		token: string;
		booking: BookingCheckout;
	}>();
	const [checkoutError, setCheckoutError] = useState(false);
	const { Link, resolve } = usePluginSiteNavigation(CALENDAR_PLUGIN_ID);
	const isCurrent = useCheckoutContext(token);
	const booking =
		confirmation?.token === token ? confirmation.booking : undefined;
	const pending = verify.isPending || cancel.isPending || accept.isPending;
	const error = verify.error || cancel.error || accept.error;
	const offerExpired =
		!!entry.offerExpiresAt && Date.parse(entry.offerExpiresAt) <= Date.now();
	const expired =
		Date.parse(entry.expiresAt) <= Date.now() || entry.status === "expired";
	const active =
		!expired && ["unverified", "waiting", "offered"].includes(entry.status);
	const acceptOffer = async () => {
		try {
			const result = await accept.mutateAsync(token);
			if (!isCurrent()) return;
			setConfirmation({ token, booking: result });
			if (result.checkout?.redirectUrl) {
				try {
					openCalendarCheckout(result, result.checkout.redirectUrl);
				} catch {
					setCheckoutError(true);
				}
			}
		} catch {
			// The mutation exposes offer expiry and booking errors below.
		}
	};
	return (
		<CalendarPage>
			<section className="max-w-xl space-y-5" aria-live="polite">
				<h1 className="text-2xl font-semibold sm:text-3xl">
					{booking
						? booking.status === "pending_payment"
							? "Booking awaiting payment"
							: booking.status === "cancelled"
								? "Booking cancelled"
								: "Booking confirmed"
						: "Manage waitlist"}
				</h1>
				<h2 className="break-words text-xl">{entry.eventName}</h2>
				<p>
					{formatCalendarTime(entry.start, entry.timezone)} ({entry.timezone})
				</p>
				{booking ? (
					<>
						{booking.status === "cancelled" ? (
							<p>Your booking has been cancelled.</p>
						) : (
							<>
								<CalendarPayment booking={booking} />
								<CalendarInviteDownload booking={booking} />
							</>
						)}
						{checkoutError && (
							<p role="alert">
								Save your private booking link and enable browser storage before
								continuing payment.
							</p>
						)}
						<Button className="min-h-11" variant="outline" asChild>
							<Link
								href={resolve("calendar", "cancel", booking.cancelToken).href}
							>
								Manage or cancel booking
							</Link>
						</Button>
					</>
				) : entry.status === "cancelled" ? (
					<p>Your waitlist entry has been cancelled.</p>
				) : entry.status === "accepted" ? (
					<>
						<p>
							Your offer has been accepted. View your booking to manage it or
							continue payment.
						</p>
						<Button
							className="min-h-11"
							disabled={pending}
							onClick={() => void acceptOffer()}
						>
							{accept.isPending ? "Loading booking…" : "View booking"}
						</Button>
					</>
				) : expired ? (
					<p>Your waitlist entry has expired. No booking was confirmed.</p>
				) : entry.status === "unverified" ? (
					<>
						<p>
							Verify your email to join the waitlist for this time. This does
							not confirm a booking or charge you.
						</p>
						<Button
							className="min-h-11"
							disabled={pending}
							onClick={() => verify.mutate(token)}
						>
							{verify.isPending
								? "Verifying email…"
								: "Verify email and join waitlist"}
						</Button>
					</>
				) : entry.status === "offered" && !offerExpired ? (
					<>
						<p>
							A place is available. Accept by{" "}
							{formatCalendarTime(entry.offerExpiresAt!, entry.timezone)} (
							{entry.timezone}).
						</p>
						<p className="text-sm text-muted-foreground">
							Accepting follows the event's usual booking and payment rules.
							Paid bookings remain pending until payment is confirmed.
						</p>
						<Button
							className="min-h-11"
							disabled={pending}
							onClick={() => void acceptOffer()}
						>
							{accept.isPending ? "Accepting offer…" : "Accept offer"}
						</Button>
					</>
				) : (
					<p>
						{offerExpired
							? "This offer has expired. No booking was confirmed."
							: "You are on the waitlist. If a place opens, you will receive a time-limited offer. No booking is confirmed yet."}
					</p>
				)}
				{error && (
					<p role="alert" className="text-destructive">
						{error.message}
					</p>
				)}
				{!booking && active && (
					<div className="flex flex-wrap gap-3">
						<Button
							className="min-h-11"
							variant="outline"
							disabled={pending || isFetching}
							onClick={() => void refetch()}
						>
							Check waitlist status
						</Button>
						<Button
							className="min-h-11"
							variant="destructive"
							disabled={pending}
							onClick={() => cancel.mutate(token)}
						>
							{cancel.isPending ? "Leaving waitlist…" : "Leave waitlist"}
						</Button>
					</div>
				)}
				<p className="text-sm text-muted-foreground">
					Keep this private link secure. Anyone with it can manage this waitlist
					entry.
				</p>
			</section>
		</CalendarPage>
	);
}

"use client";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { usePluginOverrides } from "@btst/stack/context";
import type { BookingCheckout } from "../../types";
import type { CalendarPluginOverrides } from "../overrides";
import { CALENDAR_PLUGIN_ID } from "../constants";
import { openCalendarCheckout, useCheckoutContext } from "./checkout";
import { useCalendarBookingCheckout } from "@btst/plugin-calendar/client/hooks";

/** Token-authorized checkout retry; credentials stay in this component's mutation response. */
export function CalendarPayment({ booking }: { booking: BookingCheckout }) {
	const retry = useCalendarBookingCheckout();
	const [redirectError, setRedirectError] = useState(false);
	const overrides =
		usePluginOverrides<CalendarPluginOverrides>(CALENDAR_PLUGIN_ID);
	const result =
		retry.data?.id === booking.id &&
		retry.data.cancelToken === booking.cancelToken
			? retry.data
			: booking;
	const isCurrentCheckout = useCheckoutContext(
		JSON.stringify([booking.id, booking.cancelToken]),
	);
	const resume = async () => {
		try {
			const next = await retry.mutateAsync(booking.cancelToken);
			if (!isCurrentCheckout()) return;
			if (next.checkout?.redirectUrl)
				openCalendarCheckout(next, next.checkout.redirectUrl);
		} catch {
			if (isCurrentCheckout()) setRedirectError(true);
		}
	};
	if (booking.status !== "pending_payment") return null;
	if (!booking.hasCheckout)
		return (
			<p role="status">
				Payment pending. Your time is held until the host confirms payment or
				the booking is cancelled.
			</p>
		);
	return (
		<div className="flex flex-col gap-3">
			<p role="status">Your time is held while payment is pending.</p>
			{result.checkout?.clientSecret ? (
				(overrides.renderPayment?.(result.checkout) ?? (
					<p>Payment form unavailable. Contact the host for help.</p>
				))
			) : (
				<Button
					className="min-h-11"
					disabled={retry.isPending}
					onClick={() => void resume()}
				>
					{retry.isPending ? "Opening checkout…" : "Continue payment"}
				</Button>
			)}
			{(result.checkoutError || retry.error || redirectError) && (
				<p role="alert">
					Payment could not be opened. Please try again or contact the host.
				</p>
			)}
		</div>
	);
}

"use client";

import type { ReactNode } from "react";
import type { FallbackProps } from "@btst/stack/client/components";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";

export function CalendarPage({ children }: { children: ReactNode }) {
	return (
		<div className="container mx-auto min-w-0 max-w-5xl space-y-8 px-4 py-6 sm:px-6 sm:py-8">
			{children}
		</div>
	);
}

export function CalendarLoading() {
	return (
		<CalendarPage>
			<p role="status">Loading calendar…</p>
		</CalendarPage>
	);
}

export function CalendarError({ error, resetErrorBoundary }: FallbackProps) {
	const message =
		process.env.NODE_ENV === "development" && error instanceof Error
			? error.message
			: "Calendar information could not be loaded. Check your link or try again.";
	return (
		<CalendarPage>
			<div role="alert" className="space-y-4">
				<h1 className="text-2xl font-semibold">Calendar unavailable</h1>
				<p>{message}</p>
				<Button
					className="min-h-11"
					variant="outline"
					onClick={resetErrorBoundary}
				>
					Retry loading
				</Button>
			</div>
		</CalendarPage>
	);
}

export function CalendarNotFound({ message }: { message: string }) {
	return (
		<CalendarPage>
			<h1 className="text-2xl font-semibold">Booking page not found</h1>
			<p>{message}</p>
		</CalendarPage>
	);
}

export function Field({
	label,
	id,
	children,
	hint,
}: {
	label: string;
	id: string;
	children: ReactNode;
	hint?: string;
}) {
	return (
		<div className="min-w-0 space-y-2">
			<Label htmlFor={id}>{label}</Label>
			{children}
			{hint && <p className="text-sm text-muted-foreground">{hint}</p>}
		</div>
	);
}

export const calendarSelectClass =
	"border-input bg-background min-h-11 w-full min-w-0 rounded-md border px-3 text-sm focus-visible:outline-2 focus-visible:outline-ring";

export function formatCalendarTime(value: string, timezone: string) {
	return new Intl.DateTimeFormat(undefined, {
		dateStyle: "medium",
		timeStyle: "short",
		timeZone: timezone,
	}).format(new Date(value));
}

export function formatCalendarPrice(price: number, currency: string) {
	const formatter = new Intl.NumberFormat(undefined, {
		style: "currency",
		currency,
	});
	return formatter.format(
		price / 10 ** (formatter.resolvedOptions().maximumFractionDigits ?? 2),
	);
}

"use client";

import { usePluginOverrides } from "@btst/stack/context";
import { CALENDAR_PLUGIN_ID } from "../constants";
import type { CalendarPluginOverrides } from "../overrides";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { useCalendarSlots } from "@btst/plugin-calendar/client/hooks";
import { Field, calendarSelectClass } from "./shared";

export function calendarToday(timezone: string) {
	return new Intl.DateTimeFormat("en-CA", {
		timeZone: timezone,
		year: "numeric",
		month: "2-digit",
		day: "2-digit",
	}).format(new Date());
}

export function CalendarTimePicker({
	page,
	...props
}: CalendarTimePickerProps & {
	page?: "calendarBooking" | "calendarReschedule";
}) {
	return page ? (
		<ScopedCalendarTimePicker page={page} {...props} />
	) : (
		<DefaultCalendarTimePicker {...props} />
	);
}

function ScopedCalendarTimePicker({
	page,
	...props
}: CalendarTimePickerProps & {
	page: "calendarBooking" | "calendarReschedule";
}) {
	const { pageOverrides } =
		usePluginOverrides<CalendarPluginOverrides>(CALENDAR_PLUGIN_ID);
	const Component =
		(page ? pageOverrides?.[page]?.TimePicker : undefined) ??
		DefaultCalendarTimePicker;
	return <Component {...props} />;
}

/** Values and change handlers supplied by a built-in booking page. */
export interface CalendarTimePickerProps {
	/** Selected date in YYYY-MM-DD format. */
	date: string;
	/** IANA timezone used for slot labels and queries. */
	timezone: string;
	/** Selected slot start, or an empty string. */
	start: string;
	/** Change the date; also clear the selected start. */
	onDate: (date: string) => void;
	/** Change the timezone; also clear the selected start. */
	onTimezone: (timezone: string) => void;
	/** Select a supplied slot start or clear the selection. */
	onStart: (start: string) => void;
	/** Page-owned availability result, including loading and error state. */
	slots: ReturnType<typeof useCalendarSlots>;
	/** Event capacity; defaults to one attendee. */
	capacity?: number;
	/** Include full group slots that accept a waitlist request. */
	waitlistEnabled?: boolean;
}

function DefaultCalendarTimePicker({
	date,
	timezone,
	start,
	onDate,
	onTimezone,
	onStart,
	slots,
	capacity = 1,
	waitlistEnabled = false,
}: CalendarTimePickerProps) {
	const choices = [
		...(slots.data?.slots ?? []),
		...(waitlistEnabled ? (slots.data?.waitlistSlots ?? []) : []),
	].sort((a, b) => a.start.localeCompare(b.start));
	const zones = Array.from(
		new Set([timezone, "UTC", ...Intl.supportedValuesOf("timeZone")]),
	);
	return (
		<section
			aria-labelledby="calendar-choose-time"
			className="min-w-0 space-y-5"
		>
			<h2 id="calendar-choose-time" className="text-xl font-semibold">
				Choose a time
			</h2>
			<div className="grid min-w-0 gap-4 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2">
				<Field id="calendar-date" label="Date">
					<Input
						id="calendar-date"
						className="min-h-11"
						type="date"
						required
						min={calendarToday(timezone)}
						value={date}
						onChange={(e) => {
							if (e.target.value) {
								onDate(e.target.value);
								onStart("");
							}
						}}
					/>
				</Field>
				<Field id="calendar-timezone" label="Timezone">
					<select
						id="calendar-timezone"
						className={calendarSelectClass}
						value={timezone}
						onChange={(e) => {
							onTimezone(e.target.value);
							onStart("");
						}}
					>
						{zones.map((zone) => (
							<option key={zone} value={zone}>
								{zone}
							</option>
						))}
					</select>
				</Field>
			</div>
			{slots.isPending || slots.isFetching ? (
				<p role="status">Loading available times…</p>
			) : slots.error ? (
				<div role="alert" className="space-y-3">
					<p>{slots.error.message}</p>
					<Button
						className="min-h-11"
						variant="outline"
						onClick={() => void slots.refetch()}
					>
						Retry available times
					</Button>
				</div>
			) : choices.length === 0 ? (
				<p className="rounded-lg border p-5 text-muted-foreground">
					No available times on this date. Choose another date.
				</p>
			) : (
				<div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
					{choices.map((slot) => (
						<Button
							key={slot.start}
							data-testid={
								slot.remaining === 0
									? "calendar-waitlist-slot"
									: "calendar-slot"
							}
							className="h-auto min-h-11 min-w-0 flex-col whitespace-normal px-2 py-2"
							variant={start === slot.start ? "default" : "outline"}
							aria-pressed={start === slot.start}
							onClick={() => onStart(slot.start)}
						>
							{new Intl.DateTimeFormat(undefined, {
								hour: "numeric",
								minute: "2-digit",
								timeZoneName: "short",
								timeZone: timezone,
							}).format(new Date(slot.start))}
							{capacity > 1 && (
								<span className="text-xs">
									{slot.remaining === 0
										? "Full · Join waitlist"
										: `(${slot.remaining} left)`}
								</span>
							)}
						</Button>
					))}
				</div>
			)}
		</section>
	);
}

import type { ComponentType, ReactNode } from "react";
import type { CalendarTimePickerProps } from "./components/time-picker";
import type { PaymentCheckout } from "@btst/stack/payments";

/** Browser payment customization for Calendar. */
export interface CalendarPluginOverrides {
	/** Replace time selection on booking or rescheduling pages. */
	pageOverrides?: Partial<
		Record<
			"calendarBooking" | "calendarReschedule",
			{ TimePicker?: ComponentType<CalendarTimePickerProps> }
		>
	>;
	/** Render the provider form for client-secret checkouts. Hosted checkouts redirect automatically. */
	renderPayment?: (checkout: PaymentCheckout) => ReactNode;
}
